def polynomialHullOf (e : X → σ → ℂ) (K : Set X) : Set X :=
  {x | ∀ (p : MvPolynomial σ ℂ) (C : ℝ),
    (∀ y ∈ K, ‖MvPolynomial.eval (e y) p‖ ≤ C) → ‖MvPolynomial.eval (e x) p‖ ≤ C}

